function sortString(s) {
  const count = new Array(26).fill(0);
  for (const ch of s) {
    count[ch.charCodeAt(0) - 97]++;
  }

  const result = [];
  while (result.length < s.length) {
    for (let c = 0; c < 26; c++) {
      if (count[c] > 0) {
        result.push(String.fromCharCode(97 + c));
        count[c]--;
      }
    }
    for (let c = 25; c >= 0; c--) {
      if (count[c] > 0) {
        result.push(String.fromCharCode(97 + c));
        count[c]--;
      }
    }
  }
  return result.join('');
}

