function sortString(s) {
  // Follow the rules literally on a list of remaining letters, scanning it for each pick.
  const pool = s.split('');
  let result = '';
  const take = (better, start) => {
    let last = start;
    for (;;) {
      let pick = -1;
      for (let i = 0; i < pool.length; i++) {
        if (better(pool[i], last) && (pick < 0 || better(pool[pick], pool[i]))) pick = i;
      }
      if (pick < 0) return;
      last = pool[pick];
      result += last;
      pool.splice(pick, 1);
    }
  };
  while (pool.length > 0) {
    take((a, b) => a > b, '');
    take((a, b) => a < b, '{');
  }
  return result;
}

