function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 12);
  const alphabet = large ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * 5);
  const offset = Math.floor(rand() * (27 - alphabet));
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + offset + Math.floor(rand() * alphabet));
  return [s];
}
